  function kur(K, KATEGORI) {
    /* =====================================================================
       SVG KÜTÜPHANESİ                                    (veri/veri_svg.js)
       ---------------------------------------------------------------------
       Sitenin farklı sayfalarında kullanılan animasyonlu SVG'ler burada TEK
       yerde, her biri bir kelimeye (Türkçe + Arapça) bağlı. Yeni bir
       çalışmada animasyonlu görsel gerekince önce buraya bakılır, yenisi
       çizilmez; bir SVG düzeltildikçe onu kullanan her sayfa güzelleşir.

       Her SVG BAĞIMSIZDIR: animasyonunu (@keyframes ya da SMIL) kendi
       içinde taşır, sayfanın CSS'ine ihtiyaç duymaz. Sınıf adı yoktur;
       keyframes ve id'ler "ks-<id>-" öneklidir, başka SVG'lerle çakışmaz.
       Yazı içerenler sitenin Arakom yazı tipiyle en doğru görünür.

       KULLANIM
         <script src="veri/veri_svg.js"></script>
         KidefSvg.html('kalem')                  '<svg …>' — id'ler her çağrıda benzersiz
         KidefSvg.html('قَلَم', {etiket:'Kalem'})  kelimeyle de bulunur (harekesiz de olur)
         KidefSvg.html('saat', {etiket:false})   süs: ekran okuyucudan gizli
         KidefSvg.yerlestir(kutu, 'saat')         kutunun içine koyar, <svg>'yi döndürür
         KidefSvg.bul('kitap')                    kayıt nesnesi ya da null
         KidefSvg.kategori('meslek')              o kategorideki kayıtlar
         KidefSvg.resim('kupa')                   data:image/svg+xml… (<img>, CSS için)
       Boyutu kapsayıcı belirler: SVG kutusunun genişliğini/yüksekliğini doldurur.
       İşletim sisteminde "hareketi azalt" açıksa ya da sitenin "dusuk-guc"
       kipindeyse animasyonlar durur, ilk kare görünür.

       KAYIT ALANLARI
         id     değişmez anahtar (Latin harf, rakam, tire)
         tr     Türkçe kelime       ar  Arapça (öğretmenin hareke kuralları)
         es     öteki biçimler (müennes, eş anlamlı)          kat  kategori
         kaynak SVG'nin alındığı sayfa(lar)    s  sürüm    t  son güncelleme
         svg    bağımsız SVG

       DÜZENLEME: _kaynak/arac/svg-tezgah.html (siteye bağlı değil) ve
       _kaynak/uretici/svgKutuphane.py (--denetle · --uygula · --liste).
       Her kayıt tek satırdır: git farkında yalnız değişen SVG'nin satırı
       görünür. Bu işlevin metni tezgâhın dosyayı yeniden yazarken
       kullandığı kalıptır; değiştirilirse tezgâh da aynısını yazar.
       ===================================================================== */
    var HAREKE = /[ً-ْٰـ]/g;
    function sade(s) {
      return String(s == null ? '' : s).replace(HAREKE, '').replace(/[أإآٱ]/g, 'ا')
        .replace(/ى/g, 'ي').replace(/ة/g, 'ه').toLocaleLowerCase('tr').replace(/\s+/g, ' ').trim();
    }
    var DIZIN = {};
    K.forEach(function (k) {
      [k.id, k.tr, k.ar].concat(k.es || []).forEach(function (a) {
        var s = sade(a);
        if (s && !DIZIN[s]) DIZIN[s] = k;
      });
    });
    function bul(ad) {
      if (!ad) return null;
      if (typeof ad === 'object') return ad;
      return DIZIN[sade(ad)] || null;
    }
    var sayac = 0, bicemVar = false;
    function bicem() {
      if (bicemVar || typeof document === 'undefined') return;
      bicemVar = true;
      var st = document.createElement('style');
      st.id = 'ksvg-bicem';
      st.textContent = '.ksvg{display:block;width:100%;height:100%}' +
        '@media (prefers-reduced-motion:reduce){.ksvg,.ksvg *{animation-play-state:paused!important}}' +
        'html.dusuk-guc .ksvg,html.dusuk-guc .ksvg *{animation-play-state:paused!important}';
      (document.head || document.documentElement).appendChild(st);
    }
    function hareketYok() {
      try {
        return (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) ||
          document.documentElement.classList.contains('dusuk-guc');
      } catch (e) { return false; }
    }
    function kacir(s) {
      return String(s).replace(/[&<>"]/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
      });
    }
    /* html(ad, ayar) — ayar: { etiket: 'erişilebilir ad' | false, sinif: 'ek sınıf' } */
    function html(ad, ayar) {
      var k = bul(ad);
      if (!k) return '';
      ayar = ayar || {};
      bicem();
      var n = ++sayac, on = 'ks-' + k.id + '-i';
      var s = k.svg.split(on).join('ks-' + k.id + '-' + n + 'i');
      var etiket = ayar.etiket === false ? '' : (ayar.etiket || k.tr);
      var nit = ' class="ksvg ksvg-' + k.id + (ayar.sinif ? ' ' + kacir(ayar.sinif) : '') + '"' +
        (etiket ? ' role="img" aria-label="' + kacir(etiket) + '"' : ' aria-hidden="true"') +
        ' focusable="false" data-ksvg="' + k.id + '"';
      return s.replace(/^<svg\b/, '<svg' + nit);
    }
    function yerlestir(el, ad, ayar) {
      if (!el) return null;
      el.innerHTML = html(ad, ayar);
      var s = el.querySelector('svg');
      if (s && hareketYok()) { try { s.pauseAnimations(); } catch (e) {} }
      return s;
    }
    function resim(ad) {
      var k = bul(ad);
      return k ? 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(k.svg) : '';
    }
    function kategori(kat) {
      return K.filter(function (k) { return k.kat === kat; });
    }
    window.KIDEF_SVG = K;
    window.KidefSvg = {
      liste: K, kategoriler: KATEGORI, bul: bul, html: html, yerlestir: yerlestir,
      resim: resim, kategori: kategori, sade: sade, _kur: kur
    };
  }
